using Unity.AI.Navigation;
using UnityEngine;
using UnityEngine.AI;

namespace SkyCoin
{
    /// <summary>
    /// Bakes the navigation mesh when the level starts, instead of requiring a manual bake
    /// from the Navigation window.
    ///
    /// WHY RUNTIME BAKING:
    ///   - the level is generated by an editor tool, so a baked asset would have to be
    ///     regenerated by hand every time the geometry changes,
    ///   - a build cannot rely on an editor time bake at all,
    ///   - it is a single, visible line of setup rather than a sequence of window clicks.
    ///
    /// COST: a few milliseconds once, at the moment the level loads. Acceptable for a
    /// level of this size. For a much larger level, bake it in the editor instead
    /// (select the NavMesh object, press Bake) and delete this component.
    ///
    /// The surface only collects the GROUND layer, so coins, the player, the enemy and
    /// hazards can never become navigation surfaces.
    /// </summary>
    [DefaultExecutionOrder(-1000)]
    public class RuntimeNavMeshBaker : MonoBehaviour
    {
        [SerializeField] private NavMeshSurface surface;

        [Tooltip("Log the size of the baked mesh. Useful the first time you set up a level.")]
        [SerializeField] private bool logResult = true;

        private void Awake()
        {
            if (surface == null) surface = GetComponent<NavMeshSurface>();

            if (surface == null)
            {
                Debug.LogError("[RuntimeNavMeshBaker] No NavMeshSurface found. The enemy will not be able to move.", this);
                return;
            }

            surface.BuildNavMesh();

            if (!logResult) return;

            NavMeshTriangulation triangulation = NavMesh.CalculateTriangulation();

            if (triangulation.vertices == null || triangulation.vertices.Length == 0)
            {
                Debug.LogError("[RuntimeNavMeshBaker] The baked navigation mesh is empty. " +
                               "Check that the level geometry is on the Ground layer and has colliders.", this);
                return;
            }

            Debug.Log($"[RuntimeNavMeshBaker] Navigation mesh ready: {triangulation.vertices.Length} vertices, " +
                      $"{triangulation.indices.Length / 3} triangles.");
        }
    }
}
